{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for this S3 bucket. Without logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled for this S3 bucket. Without versioning, it is not possible to recover from accidental deletions or overwrites of objects."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration. This can lead to unnecessary storage costs and inefficient data management."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not encrypted with a KMS key. This increases the risk of data exposure if the bucket is compromised."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
  }, {})

  logging {
    target_bucket = "${local.resource_prefix.value}-logs"
    target_prefix = "financials/"
  }

  versioning {
    enabled = true
  }

  lifecycle_rule {
    id      = "expire-old-versions"
    enabled = true

    noncurrent_version_expiration {
      days = 30
    }
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket                  = aws_s3_bucket.financials.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Enabled access logging, versioning, lifecycle rules, and server-side encryption with KMS for the S3 bucket. Added a Public Access Block to prevent accidental public exposure."
}
